// ═════════ YOUR SEARCH — edit these ═════════
const config = {
  // Roles you want (case-insensitive substring match on the job title):
  keywords: ["platform","devops","dev ops","sre","site reliability","cloud engineer","infrastructure","kubernetes","platform engineer"],

  // Work arrangement: "remote" | "hybrid" | "onsite".
  // Flexible to the ADJACENT type (remote<->hybrid, hybrid<->onsite) but never the opposite:
  // remote => never on-site-only; onsite => never remote-only; hybrid => anything goes.
  workArrangement: "remote",

  // WHERE you can work — HARD requirement. Lowercased substring tokens. A role tied to any place
  // NOT covered here is dropped; global / remote-anywhere always qualifies.
  // EU example below. US seeker: ["united states","usa","remote us"]; one country: ["germany","berlin"].
  locationAllow: ["worldwide","global","anywhere","emea","europe","european","eu","eea","your country"],

  // Only email roles the LLM scores at least this (0-100):
  scoreThreshold: 80,

  // Who you are — the LLM scores fit against this (REPLACE with your own CV summary):
  candidateProfile: [
    "CANDIDATE PROFILE (replace with your own):",
    "- Senior platform / DevOps / SRE engineer, ~8 years.",
    "- Core: Kubernetes, GitOps (ArgoCD/Flux), Terraform, CI/CD, Linux, cloud (AWS/GCP).",
    "- Also: observability (Prometheus/Grafana), secrets management, automation.",
    "- Weaker fit: pure frontend, pure ML research, management-only roles."
  ].join("\n"),

  // ───────── delivery / engine (set once) ─────────
  emailFrom: "you@example.com",
  emailTo: "you@example.com",
  // OpenAI-compatible chat endpoint. Default: NVIDIA NIM hosted API (needs an HTTP Header Auth
  // credential on the 'Score (LLM)' node: name=Authorization, value="Bearer <your-key>").
  // Or point at a self-hosted NIM/Ollama and set the node's auth to None.
  llmUrl: "https://integrate.api.nvidia.com/v1/chat/completions",
  llmModel: "meta/llama-3.1-8b-instruct",
  pollHours: 6,
  maxScorePerRun: 150,       // cap LLM calls per run (scores newest first)
  himalayas: { enabled: true, pages: 3, perPage: 100 },  // broad 'no company list' source

  // ───────── sources: companies on the 3 public ATS (tokens verified live) ─────────
  companies: [
    { company: "GitLab",         ats_type: "greenhouse", token: "gitlab",      enabled: true },
    { company: "Grafana Labs",   ats_type: "greenhouse", token: "grafanalabs", enabled: true },
    { company: "Canonical",      ats_type: "greenhouse", token: "canonical",   enabled: true },
    { company: "Mistral AI",     ats_type: "lever",      token: "mistral",     enabled: true },
    { company: "Supabase",       ats_type: "ashby",      token: "supabase",    enabled: true },
    { company: "Modal",          ats_type: "ashby",      token: "modal",       enabled: true },
    { company: "Baseten",        ats_type: "ashby",      token: "baseten",     enabled: true },
    { company: "Vercel",         ats_type: "greenhouse", token: "vercel",               enabled: true },
    { company: "Cockroach Labs", ats_type: "greenhouse", token: "cockroachlabs",        enabled: true },
    { company: "ClickHouse",     ats_type: "greenhouse", token: "clickhouse",           enabled: true },
    { company: "Temporal",       ats_type: "greenhouse", token: "temporaltechnologies", enabled: true },
    { company: "Tailscale",      ats_type: "greenhouse", token: "tailscale",            enabled: true },
    { company: "Elastic",        ats_type: "greenhouse", token: "elastic",              enabled: true },
    { company: "Render",         ats_type: "ashby",      token: "render",               enabled: true },
    { company: "Railway",        ats_type: "ashby",      token: "railway",              enabled: true },
    { company: "Sentry",         ats_type: "ashby",      token: "sentry",               enabled: true },
    { company: "Coder",          ats_type: "ashby",      token: "coder",                enabled: true },
    { company: "Confluent",      ats_type: "ashby",      token: "confluent",            enabled: true },
    { company: "Docker",         ats_type: "ashby",      token: "docker",               enabled: true },
    { company: "Sysdig",         ats_type: "lever",      token: "sysdig",               enabled: true },
    { company: "Scaleway",       ats_type: "lever",      token: "scaleway",             enabled: true },
    { company: "Together AI",    ats_type: "greenhouse", token: "togetherai",  enabled: true },
    { company: "Fireworks AI",   ats_type: "greenhouse", token: "fireworksai", enabled: true },
    { company: "RunPod",         ats_type: "greenhouse", token: "runpod",      enabled: true },
    { company: "CoreWeave",      ats_type: "greenhouse", token: "coreweave",   enabled: true },
    { company: "Comet",          ats_type: "greenhouse", token: "comet",       enabled: true },
    { company: "Anyscale",       ats_type: "ashby",      token: "anyscale",    enabled: true },
    { company: "Cohere",         ats_type: "ashby",      token: "cohere",      enabled: true },
    { company: "Weaviate",       ats_type: "ashby",      token: "weaviate",    enabled: true },
    { company: "Pinecone",       ats_type: "ashby",      token: "pinecone",    enabled: true },
    { company: "WorkOS",         ats_type: "ashby",      token: "workos",      enabled: true },
    { company: "Stytch",         ats_type: "ashby",      token: "stytch",      enabled: true },
    { company: "1Password",      ats_type: "ashby",      token: "1password",   enabled: true }
  ]
};
return [{ json: config }];

// One fetch per enabled company, isolated by try/catch so a bad source can't kill the run.
const cfg = $('Config').first().json;
const out = [];
const s = (v) => (v == null ? '' : String(v));
const strip = (h) => s(h)
  .replace(/<[^>]*>/g, ' ')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
  .replace(/&nbsp;/g, ' ').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ').trim().slice(0, 1500);
const H = (typeof $helpers !== 'undefined' && $helpers && $helpers.httpRequest) ? $helpers : this.helpers;

for (const c of cfg.companies) {
  if (!c.enabled) continue;
  let url;
  if (c.ats_type === 'greenhouse') url = `https://boards-api.greenhouse.io/v1/boards/${c.token}/jobs?content=true`;
  else if (c.ats_type === 'lever') url = `https://api.lever.co/v0/postings/${c.token}?mode=json`;
  else if (c.ats_type === 'ashby') url = `https://api.ashbyhq.com/posting-api/job-board/${c.token}?includeCompensation=true`;
  else continue;

  let body;
  try {
    body = await H.httpRequest({ method: 'GET', url, json: true, timeout: 20000 });
  } catch (e) {
    out.push({ json: { __error: true, company: c.company, reason: ('fetch failed: ' + s(e.statusCode) + ' ' + s(e.message)).trim() } });
    continue;
  }

  try {
    if (c.ats_type === 'greenhouse') {
      for (const j of (body.jobs || [])) {
        out.push({ json: { company: c.company, title: s(j.title), location: s(j.location && j.location.name), remote: 'uncertain', url: s(j.absolute_url), posted_at: s(j.updated_at), comp: '', description: strip(j.content), external_id: 'greenhouse:' + c.company + ':' + j.id } });
      }
    } else if (c.ats_type === 'lever') {
      for (const j of (Array.isArray(body) ? body : [])) {
        const wt = s(j.workplaceType).toLowerCase();
        out.push({ json: { company: c.company, title: s(j.text), location: s(j.categories && j.categories.location), remote: wt === 'remote' ? 'true' : (wt ? 'false' : 'uncertain'), url: s(j.hostedUrl), posted_at: j.createdAt ? new Date(j.createdAt).toISOString() : '', comp: '', description: strip(j.descriptionPlain || j.description), external_id: 'lever:' + c.company + ':' + j.id } });
      }
    } else if (c.ats_type === 'ashby') {
      for (const j of (body.jobs || [])) {
        out.push({ json: { company: c.company, title: s(j.title), location: s(j.location || j.locationName), remote: j.isRemote === true ? 'true' : (j.isRemote === false ? 'false' : 'uncertain'), url: s(j.jobUrl || j.applyUrl), posted_at: s(j.publishedAt), comp: s(j.compensation && j.compensation.compensationTierSummary), description: strip(j.descriptionPlain || j.descriptionHtml), external_id: 'ashby:' + c.company + ':' + j.id } });
      }
    }
  } catch (e) {
    out.push({ json: { __error: true, company: c.company, reason: 'normalize: ' + s(e.message) } });
  }
}

// ── Himalayas: broad 'no company list' source (newest remote jobs across all companies) ──
if (cfg.himalayas && cfg.himalayas.enabled) {
  const per = cfg.himalayas.perPage || 100;
  const pages = cfg.himalayas.pages || 3;
  for (let p = 0; p < pages; p++) {
    let hb;
    try {
      hb = await H.httpRequest({ method: 'GET', url: 'https://himalayas.app/jobs/api?limit=' + per + '&offset=' + (p * per), json: true, timeout: 20000 });
    } catch (e) {
      out.push({ json: { __error: true, company: 'Himalayas', reason: 'fetch failed: ' + s(e.message) } });
      break;
    }
    for (const j of ((hb && hb.jobs) || [])) {
      const restr = Array.isArray(j.locationRestrictions) ? j.locationRestrictions.join(', ') : s(j.locationRestrictions);
      out.push({ json: {
        company: s(j.companyName) || 'unknown', title: s(j.title), location: restr, remote: 'true',
        url: s(j.guid || j.applicationLink), posted_at: j.pubDate ? new Date(j.pubDate * 1000).toISOString() : '',
        comp: (j.minSalary && j.maxSalary) ? (j.minSalary + '-' + j.maxSalary + ' ' + s(j.currency)) : '',
        description: strip(j.description || j.excerpt), external_id: 'himalayas:' + s(j.guid || j.title)
      }});
    }
  }
}

return out;

// Cheap deterministic gate: title keyword + ALLOW-ONLY location.
// Allow-only fixes the deny-list leak: anything naming a place you didn't allow is dropped
// (so 'Remote (Colombia)' dies here). The LLM re-checks location as a hard gate downstream.
const cfg = $('Config').first().json;
const kw = (cfg.keywords || cfg.roleKeywords || []).map(x => x.toLowerCase());
const allow = (cfg.locationAllow || []).map(x => x.toLowerCase());
const GLOBAL = ['worldwide','global','anywhere','remote anywhere','fully remote','work from anywhere'];
const GENERIC = ['remote','hybrid','on-site','on site','onsite','home based','home-based','home','based','office','wfh','work from home','distributed','flexible','fully','partially','telecommute'];

const locPass = (raw) => {
  const loc = (raw || '').toLowerCase().trim();
  if (loc === '') return true;                         // unknown -> let the LLM decide
  if (GLOBAL.some(g => loc.includes(g))) return true;  // global / anywhere remote
  if (allow.some(t => loc.includes(t))) return true;   // an allowed region/country is named
  let residual = loc;
  for (const g of GENERIC) residual = residual.split(g).join(' ');
  residual = residual.replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
  return residual === '';                               // only work-type words left (bare remote) -> ok; a named place -> drop
};

const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.__error) continue;
  const title = (j.title || '').toLowerCase();
  if (!kw.some(k => title.includes(k))) continue;
  if (locPass(j.location)) out.push({ json: j });
}
return out;

// One scoring request PER new job. LLM checks location (hard), arrangement (flexible), and fit.
const cfg = $('Config').first().json;
const clip = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n);
const cap = cfg.maxScorePerRun || 150;
const jobs = $input.all().map(it => it.json)
  .sort((a, b) => String(b.posted_at || '').localeCompare(String(a.posted_at || '')))
  .slice(0, cap);

const arr = (cfg.workArrangement || 'remote').toLowerCase();
const arrRule = arr === 'onsite'
  ? 'Candidate wants ON-SITE. On-site or hybrid is acceptable; remote-only is NOT.'
  : arr === 'hybrid'
  ? 'Candidate wants HYBRID. Hybrid, remote, or on-site are all acceptable.'
  : 'Candidate wants REMOTE. Remote or hybrid is acceptable; on-site-only is NOT.';

const sys = cfg.candidateProfile + '\n\n' +
  'Evaluate the job for this candidate. Return ONLY a JSON object: ' +
  '{"location_ok": <bool>, "arrangement_ok": <bool>, "score": <int 0-100>, "reason": "<max 14 words>"}.\n' +
  'HARD LOCATION: the role must be doable from one of [' + (cfg.locationAllow || []).join(', ') + '] OR be globally/anywhere remote. ' +
  'A role restricted to any OTHER specific country/region => location_ok=false.\n' +
  'ARRANGEMENT: ' + arrRule + ' Set arrangement_ok accordingly; if the listing is unclear, default true.\n' +
  'Desired role focus: ' + (cfg.keywords || []).join(', ') + '.\n' +
  'score = fit on skills/seniority/domain only (do NOT fold location/arrangement into the number; those are the booleans).';

return jobs.map(j => {
  const user = 'Job:\n' + JSON.stringify({ company: j.company, title: j.title, location: j.location, description: clip(j.description, 600) });
  const body = { model: cfg.llmModel, messages: [ { role: 'system', content: sys }, { role: 'user', content: user } ], temperature: 0.1, max_tokens: 200 };
  return { json: { external_id: j.external_id, bodyJson: JSON.stringify(body) } };
});

// Keep only roles that pass the LLM's hard gates (location_ok && arrangement_ok) AND score >= threshold.
// Mark ALL new jobs seen regardless, so nothing re-scores forever.
const cfg = $('Config').first().json;
const threshold = cfg.scoreThreshold || 80;
const fresh = $('Keep only new').all().map(i => i.json);
const failures = [...new Set(
  $('Fetch & normalize').all().map(i => i.json).filter(j => j.__error).map(j => j.company)
)];

if (fresh.length === 0) return [];

const prompts = $('Build score prompt').all().map(i => i.json);
const responses = $input.all().map(i => i.json);
const map = {};
for (let i = 0; i < responses.length; i++) {
  const id = prompts[i] && prompts[i].external_id;
  if (!id) continue;
  try {
    const r = responses[i];
    let c = (r && r.choices && r.choices[0] && r.choices[0].message) ? (r.choices[0].message.content || '') : '';
    const m = c.match(/\{[\s\S]*\}/);
    if (m) c = m[0];
    const o = JSON.parse(c);
    map[id] = { score: Number(o.score), location_ok: o.location_ok !== false, arrangement_ok: o.arrangement_ok !== false, reason: String(o.reason || '') };
  } catch (e) { /* unscored -> excluded */ }
}
for (const j of fresh) {
  const sc = map[j.external_id];
  j._score = (sc && Number.isFinite(sc.score)) ? sc.score : null;
  j._reason = sc ? sc.reason : '';
  j._ok = !!(sc && sc.location_ok && sc.arrangement_ok);
}

const hits = fresh.filter(j => j._ok && j._score != null && j._score >= threshold).sort((a, b) => b._score - a._score);

const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = hits.map(j => {
  const loc = j.location ? (' (' + esc(j.location) + ')') : '';
  const comp = j.comp ? (' — ' + esc(j.comp)) : '';
  const why = j._reason ? (' — <i>' + esc(j._reason) + '</i>') : '';
  return '<li><b>' + j._score + '%</b> — <b>' + esc(j.company) + '</b> — ' + esc(j.title) + loc + comp + why + ' — <a href="' + esc(j.url) + '">link</a></li>';
}).join('');

const n = hits.length;
let html = '<p><b>' + n + ' new role' + (n === 1 ? '' : 's') + ' scoring ' + threshold + '%+</b> (of ' + fresh.length + ' new postings, best first)</p><ul>' + rows + '</ul>';
let subject = n + ' new ' + threshold + '%+ match' + (n === 1 ? '' : 'es');
if (failures.length) {
  html += '<p style="color:#b00">⚠️ ' + failures.length + ' source(s) failing: ' + failures.map(esc).join(', ') + '</p>';
}
return [{ json: { subject, html, count80: n, freshRows: fresh } }];

// Email already sent (or skipped on the no-match branch): expand the digest's freshRows
// into one item per posting to insert into the seen-jobs table.
const rows = ($('Build digest').first().json.freshRows) || [];
return rows.map(r => ({ json: { external_id: r.external_id, company: r.company, title: r.title, location: r.location || '', url: r.url } }));
